using System;
using System.Threading.Tasks;
class C
{
    static async Task Main()
    {
        Console.Write("1");
        await Task.Yield();
        Console.Write("2");
        using (new R())
        {
            Console.Write("3");
        }
        Console.Write("4");
        await Task.Yield();
        Console.Write("5");
    }
}
ref struct R
{
    public R() => Console.Write("C");
    public void Dispose() => Console.Write("D");
}

